package com.ecommerce.inventory.service; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="inventory",indexes=@Index(name="idx_inventory_product",columnList="product_id",unique=true)) public class Inventory { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true) private UUID productId; @Column(nullable=false) private int available; @Version private long version; public UUID getId(){return id;} public UUID getProductId(){return productId;} public void setProductId(UUID v){productId=v;} public int getAvailable(){return available;} public void setAvailable(int v){available=v;} public long getVersion(){return version;} }